solution.javascript:
function plusLongPalindrome(texte) {
  const c = [...texte];
  let debut = 0;
  let longueur = 0;
  for (let centre = 0; centre < c.length; centre++) {
    for (const decalage of [0, 1]) {
      let g = centre;
      let d = centre + decalage;
      while (g >= 0 && d < c.length && c[g] === c[d]) {
        g--;
        d++;
      }
      if (d - g - 1 > longueur) {
        longueur = d - g - 1;
        debut = g + 1;
      }
    }
  }
  return c.slice(debut, debut + longueur).join("");
}

solution.python:
def plus_long_palindrome(texte):
    debut = 0
    longueur = 0
    for centre in range(len(texte)):
        for decalage in (0, 1):
            g = centre
            d = centre + decalage
            while g >= 0 and d < len(texte) and texte[g] == texte[d]:
                g -= 1
                d += 1
            if d - g - 1 > longueur:
                longueur = d - g - 1
                debut = g + 1
    return texte[debut:debut + longueur]

